function parseAttributes(input: string) {
  const attributes: Record<string, string> = {}
  for (const match of input.matchAll(/(\w+)="([^"]*)"/g)) {
    attributes[match[1]] = match[2]
  }
  return attributes
}

function parseFrontmatter(source: string, slug: string): ParsedDoc {
  const match = source.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/)
  const frontmatter = match?.[1] ?? ''
  const body = match?.[2] ?? source
  const rawTitle =
    frontmatter.match(/^title:\s*(.+)$/m)?.[1]?.trim() ?? 'Documentation'
  const quotedTitle = rawTitle.match(/^"(.*)"$/)
  const title = quotedTitle?.[1] ?? rawTitle

  return {
    title,
    slug,
    href: slug === 'index' ? '/docs' : `/docs/${slug}`,
    body,
    headings: collectHeadings(body),
  }
}

function slugify(value: string) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
}

function uniqueHeadingId(title: string, counts: Map<string, number>) {
  const base = slugify(title)
  const count = counts.get(base) ?? 0
  counts.set(base, count + 1)
  return count === 0 ? base : `${base}-${count}`
}

function collectHeadings(body: string) {
  const counts = new Map<string, number>()
  const headings: Heading[] = []

  for (const line of body.split('\n')) {
    const match = line.match(/^(#{2,3})\s+(.+)$/)
    if (!match) {
      continue
    }

    headings.push({
      id: uniqueHeadingId(stripInlineMarkdown(match[2]), counts),
      level: match[1].length as 2 | 3,
      title: stripInlineMarkdown(match[2]),
    })
  }

  return headings
}

