import fs from 'node:fs';
import path from 'node:path';

export function assertAbsoluteDirectory(directoryPath, label) {
  if (typeof directoryPath !== 'string' || !path.isAbsolute(directoryPath)) {
    throw new Error(`${label} must be an absolute path.`);
  }

  const resolved = path.resolve(directoryPath);
  if (resolved === path.parse(resolved).root) {
    throw new Error(`${label} cannot be a filesystem root.`);
  }

  assertNoSymlinkPathSegments(resolved, label);
  let stat;
  try {
    stat = fs.lstatSync(resolved);
  } catch (error) {
    if (error?.code === 'ENOENT') {
      throw new Error(`${label} does not exist: ${resolved}`);
    }
    throw error;
  }
  if (!stat.isDirectory() || stat.isSymbolicLink()) {
    throw new Error(`${label} must be a real directory: ${resolved}`);
  }
  return resolved;
}

export function assertNoSymlinkPathSegments(targetPath, label = 'Path') {
  const absolutePath = path.resolve(targetPath);
  const parsed = path.parse(absolutePath);
  const segments = absolutePath
    .slice(parsed.root.length)
    .split(path.sep)
    .filter(Boolean);
  let cursor = parsed.root;

  for (const segment of segments) {
    cursor = path.join(cursor, segment);
    let stat;
    try {
      stat = fs.lstatSync(cursor);
    } catch (error) {
      if (error?.code === 'ENOENT') return;
      throw error;
    }
    if (stat.isSymbolicLink()) {
      throw new Error(`${label} contains a symbolic link: ${cursor}`);
    }
  }
}

export function assertInside(baseDirectory, targetPath, label = 'Path') {
  const relative = path.relative(
    path.resolve(baseDirectory),
    path.resolve(targetPath),
  );
  if (
    relative === '' ||
    (!relative.startsWith(`..${path.sep}`) &&
      relative !== '..' &&
      !path.isAbsolute(relative))
  ) {
    return;
  }
  throw new Error(`${label} escapes its allowed directory.`);
}

export function normalizeRelativePosixPath(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`${label} must be a non-empty relative path.`);
  }
  if (value.includes('\\') || value.includes('\0')) {
    throw new Error(
      `${label} contains an unsafe path separator or null byte: ${value}`,
    );
  }
  if (path.posix.isAbsolute(value)) {
    throw new Error(`${label} must be relative: ${value}`);
  }

  const segments = value.split('/');
  if (
    segments.some(
      (segment) => segment === '' || segment === '.' || segment === '..',
    )
  ) {
    throw new Error(`${label} contains an unsafe path segment: ${value}`);
  }
  const normalized = path.posix.normalize(value);
  if (normalized !== value || normalized.startsWith('../')) {
    throw new Error(`${label} is not normalized: ${value}`);
  }
  return normalized;
}

export function listTree(rootDirectory, label = 'Directory') {
  const root = assertAbsoluteDirectory(rootDirectory, label);
  const files = [];
  const directories = [];
  const comparisonKeys = new Map();

  const visit = (absoluteDirectory, relativeDirectory = '') => {
    const entries = fs
      .readdirSync(absoluteDirectory, { withFileTypes: true })
      .sort((left, right) => left.name.localeCompare(right.name));
    for (const entry of entries) {
      const relativePath = relativeDirectory
        ? `${relativeDirectory}/${entry.name}`
        : entry.name;
      normalizeRelativePosixPath(relativePath, `${label} entry`);
      const key = relativePath.normalize('NFKC').toLocaleLowerCase('en-US');
      const collision = comparisonKeys.get(key);
      if (collision) {
        throw new Error(
          `Case-insensitive path collision in ${label}: "${collision}" and "${relativePath}".`,
        );
      }
      comparisonKeys.set(key, relativePath);

      const absolutePath = path.join(absoluteDirectory, entry.name);
      const stat = fs.lstatSync(absolutePath);
      if (stat.isSymbolicLink()) {
        throw new Error(`${label} contains a symbolic link: ${relativePath}`);
      }
      if (stat.isDirectory()) {
        directories.push(relativePath);
        visit(absolutePath, relativePath);
      } else if (stat.isFile()) {
        files.push(relativePath);
      } else {
        throw new Error(
          `${label} contains a non-regular entry: ${relativePath}`,
        );
      }
    }
  };

  visit(root);
  return { directories, files };
}

export function pathExists(targetPath) {
  try {
    fs.lstatSync(targetPath);
    return true;
  } catch (error) {
    if (error?.code === 'ENOENT') return false;
    throw error;
  }
}

export function removeRealTree(targetPath, allowedRoot) {
  assertInside(allowedRoot, targetPath, 'Removal target');
  if (path.resolve(targetPath) === path.resolve(allowedRoot)) {
    throw new Error(
      `Refusing to remove the allowed root itself: ${allowedRoot}`,
    );
  }
  if (!pathExists(targetPath)) return;
  const stat = fs.lstatSync(targetPath);
  if (stat.isSymbolicLink()) {
    throw new Error(`Refusing to remove a symbolic link: ${targetPath}`);
  }
  fs.rmSync(targetPath, { force: true, recursive: true });
}

#!/usr/bin/env node

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  DOCS_TESTS_BUNDLE_FILE,
  DOCS_TESTS_MANIFEST_FILE,
  GENERATED_GUIDE_SLUGS,
  LEGACY_GENERATED_ASSET_FILES,
} from './config.mjs';
import {
  assertAbsoluteDirectory,
  assertInside,
  assertNoSymlinkPathSegments,
  listTree,
  normalizeRelativePosixPath,
  pathExists,
  removeRealTree,
} from './filesystem.mjs';

const REPOSITORY_ROOT = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../..',
);
const ALLOWED_IMAGE_TYPES = new Map([
  ['.gif', 'image/gif'],
  ['.jpeg', 'image/jpeg'],
  ['.jpg', 'image/jpeg'],
  ['.png', 'image/png'],
  ['.webp', 'image/webp'],
]);
const ROOT_METADATA_FILES = new Set([
  DOCS_TESTS_BUNDLE_FILE,
  DOCS_TESTS_MANIFEST_FILE,
]);
const OUTPUT_MANIFEST_SCHEMA = 'docs-tests.output-manifest/v1alpha1';
const CONTENT_HASH_PATTERN = /^sha256:[a-f0-9]{64}$/;

function parseArguments(argv) {
  let sourceRoot;
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === '--help' || argument === '-h') return { help: true };
    if (argument === '--source') {
      sourceRoot = argv[index + 1];
      index += 1;
      continue;
    }
    if (argument.startsWith('--source=')) {
      sourceRoot = argument.slice('--source='.length);
      continue;
    }
    throw new Error(`Unknown argument: ${argument}`);
  }
  if (!sourceRoot) {
    throw new Error('Missing required --source /absolute/path argument.');
  }
  return { help: false, sourceRoot };
}

function printHelp() {
  console.log(`Copy locally generated Evorto guides into this Pages worktree.

Usage:
  npm run docs:sync -- --source /absolute/path/to/generated-docs

The source must contain content/ and assets/. Only the fixed 13 generated guide
slugs are replaced. docs-tests.bundle.json and .docs-tests-manifest.json are
validated as metadata and are never copied into the route tree. The
known flat screenshot pool from the legacy generator is removed only after the
new guide bundle has passed validation.`);
}

function readJson(filePath, label) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (error) {
    throw new Error(`Unable to read ${label}: ${filePath}`, { cause: error });
  }
}

function assertExactSet(actualValues, expectedValues, label) {
  const actual = [...new Set(actualValues)].sort();
  const expected = [...new Set(expectedValues)].sort();
  if (
    actual.length !== actualValues.length ||
    expected.length !== expectedValues.length ||
    actual.length !== expected.length ||
    actual.some((value, index) => value !== expected[index])
  ) {
    const missing = expected.filter((value) => !actual.includes(value));
    const unexpected = actual.filter((value) => !expected.includes(value));
    throw new Error(
      `${label} does not match the expected inventory.` +
        (missing.length ? ` Missing: ${missing.join(', ')}.` : '') +
        (unexpected.length ? ` Unexpected: ${unexpected.join(', ')}.` : ''),
    );
  }
}

function assertExactObjectKeys(value, expectedKeys, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${label} must be an object.`);
  }
  const actualKeys = Object.keys(value).sort();
  const expected = [...expectedKeys].sort();
  if (
    actualKeys.length !== expected.length ||
    actualKeys.some((key, index) => key !== expected[index])
  ) {
    throw new Error(`${label} has an unsupported shape.`);
  }
  return value;
}

function fileContentHash(filePath) {
  return `sha256:${crypto
    .createHash('sha256')
    .update(fs.readFileSync(filePath))
    .digest('hex')}`;
}

function normalizeManifestInventory(value, label) {
  if (
    !Array.isArray(value) ||
    value.some((entry) => typeof entry !== 'string')
  ) {
    throw new Error(`${label} must be an array of paths.`);
  }
  return value.map((relativePath, index) =>
    normalizeRelativePosixPath(relativePath, `${label} entry ${index}`),
  );
}

function validateManifestHashes({ expectedPaths, hashes, label, root }) {
  if (!hashes || typeof hashes !== 'object' || Array.isArray(hashes)) {
    throw new Error(`${label} must be an object.`);
  }

  const normalizedHashes = new Map();
  for (const [relativePath, expectedHash] of Object.entries(hashes)) {
    const normalizedPath = normalizeRelativePosixPath(
      relativePath,
      `${label} path`,
    );
    if (
      typeof expectedHash !== 'string' ||
      !CONTENT_HASH_PATTERN.test(expectedHash)
    ) {
      throw new Error(
        `${label} has an invalid SHA-256 hash: ${normalizedPath}.`,
      );
    }
    if (normalizedHashes.has(normalizedPath)) {
      throw new Error(`${label} contains a duplicate path: ${normalizedPath}.`);
    }
    normalizedHashes.set(normalizedPath, expectedHash);
  }

  assertExactSet([...normalizedHashes.keys()], expectedPaths, `${label} paths`);
  for (const relativePath of expectedPaths) {
    const filePath = path.join(root, ...relativePath.split('/'));
    assertInside(root, filePath, 'Output manifest content');
    if (fileContentHash(filePath) !== normalizedHashes.get(relativePath)) {
      throw new Error(`Output manifest integrity mismatch: ${relativePath}.`);
    }
  }
}

function validateOutputManifest(
  contentRoot,
  assetsRoot,
  expectedPageFiles,
  assetFiles,
) {
  const manifestPath = path.join(contentRoot, DOCS_TESTS_MANIFEST_FILE);
  if (!pathExists(manifestPath)) {
    throw new Error(
      `Missing ${DOCS_TESTS_MANIFEST_FILE} in generated content.`,
    );
  }
  const stat = fs.lstatSync(manifestPath);
  if (!stat.isFile() || stat.isSymbolicLink()) {
    throw new Error(`${DOCS_TESTS_MANIFEST_FILE} must be a regular file.`);
  }

  const manifest = assertExactObjectKeys(
    readJson(manifestPath, 'docs-tests output manifest'),
    ['contentHashes', 'docs', 'images', 'schemaVersion', 'targetFingerprints'],
    'Docs-tests output manifest',
  );
  if (manifest.schemaVersion !== OUTPUT_MANIFEST_SCHEMA) {
    throw new Error(`Unsupported ${DOCS_TESTS_MANIFEST_FILE} schema.`);
  }

  const docs = normalizeManifestInventory(
    manifest.docs,
    'Output manifest documentation inventory',
  );
  const images = normalizeManifestInventory(
    manifest.images,
    'Output manifest image inventory',
  );
  const expectedDocs = [...expectedPageFiles, DOCS_TESTS_BUNDLE_FILE];
  assertExactSet(docs, expectedDocs, 'Output manifest documentation inventory');
  assertExactSet(images, assetFiles, 'Output manifest image inventory');

  const contentHashes = assertExactObjectKeys(
    manifest.contentHashes,
    ['docs', 'images'],
    'Output manifest contentHashes',
  );
  validateManifestHashes({
    expectedPaths: expectedDocs,
    hashes: contentHashes.docs,
    label: 'Output manifest documentation hashes',
    root: contentRoot,
  });
  validateManifestHashes({
    expectedPaths: assetFiles,
    hashes: contentHashes.images,
    label: 'Output manifest image hashes',
    root: assetsRoot,
  });

  const targetFingerprints = assertExactObjectKeys(
    manifest.targetFingerprints,
    ['docs', 'images'],
    'Output manifest targetFingerprints',
  );
  for (const key of ['docs', 'images']) {
    if (
      typeof targetFingerprints[key] !== 'string' ||
      !CONTENT_HASH_PATTERN.test(targetFingerprints[key])
    ) {
      throw new Error(
        `Output manifest has an invalid ${key} target fingerprint.`,
      );
    }
  }
}

function validateContentTree(contentRoot) {
  const tree = listTree(contentRoot, 'Generated content directory');
  const expectedPageFiles = GENERATED_GUIDE_SLUGS.map(
    (slug) => `${slug}/page.md`,
  );
  const unexpectedFiles = tree.files.filter(
    (relativePath) =>
      !expectedPageFiles.includes(relativePath) &&
      !ROOT_METADATA_FILES.has(relativePath),
  );
  if (unexpectedFiles.length) {
    throw new Error(
      `Generated content contains files outside the supported catalog: ${unexpectedFiles.join(', ')}.`,
    );
  }
  const unexpectedDirectories = tree.directories.filter(
    (relativePath) => !GENERATED_GUIDE_SLUGS.includes(relativePath),
  );
  if (unexpectedDirectories.length) {
    throw new Error(
      `Generated content contains unsupported directories: ${unexpectedDirectories.join(', ')}.`,
    );
  }
  const pageFiles = tree.files.filter((relativePath) =>
    relativePath.endsWith('/page.md'),
  );
  assertExactSet(pageFiles, expectedPageFiles, 'Generated content pages');

  for (const relativePath of expectedPageFiles) {
    const page = fs.readFileSync(
      path.join(contentRoot, ...relativePath.split('/')),
      'utf8',
    );
    if (!page.trim())
      throw new Error(`Generated page is empty: ${relativePath}.`);
    if (page.includes('\0'))
      throw new Error(`Generated page contains a null byte: ${relativePath}.`);
  }
  return { expectedPageFiles, tree };
}

function validateAssetsTree(assetsRoot) {
  const tree = listTree(assetsRoot, 'Generated assets directory');
  const unsupportedDirectories = tree.directories.filter(
    (relativePath) =>
      !GENERATED_GUIDE_SLUGS.includes(relativePath) &&
      !GENERATED_GUIDE_SLUGS.some((slug) =>
        relativePath.startsWith(`${slug}/`),
      ),
  );
  if (unsupportedDirectories.length) {
    throw new Error(
      `Generated assets contain unsupported directories: ${unsupportedDirectories.join(', ')}.`,
    );
  }
  const assetFiles = tree.files.filter(
    (relativePath) => !ROOT_METADATA_FILES.has(relativePath),
  );
  const unsupportedFiles = assetFiles.filter((relativePath) => {
    const [slug] = relativePath.split('/');
    return (
      !GENERATED_GUIDE_SLUGS.includes(slug) ||
      !ALLOWED_IMAGE_TYPES.has(path.posix.extname(relativePath).toLowerCase())
    );
  });
  const unexpectedRootFiles = tree.files.filter(
    (relativePath) =>
      !relativePath.includes('/') && !ROOT_METADATA_FILES.has(relativePath),
  );
  if (unsupportedFiles.length || unexpectedRootFiles.length) {
    throw new Error(
      `Generated assets contain unsupported files: ${[
        ...new Set([...unsupportedFiles, ...unexpectedRootFiles]),
      ].join(', ')}.`,
    );
  }
  return { assetFiles, tree };
}

function validateBundle(contentRoot, assetsRoot, assetFiles) {
  const bundlePath = path.join(contentRoot, DOCS_TESTS_BUNDLE_FILE);
  if (!pathExists(bundlePath)) {
    throw new Error(`Missing ${DOCS_TESTS_BUNDLE_FILE} in generated content.`);
  }
  const stat = fs.lstatSync(bundlePath);
  if (!stat.isFile() || stat.isSymbolicLink()) {
    throw new Error(`${DOCS_TESTS_BUNDLE_FILE} must be a regular file.`);
  }

  const bundle = readJson(bundlePath, 'docs-tests bundle');
  if (
    !bundle ||
    typeof bundle !== 'object' ||
    bundle.schemaVersion !== 'docs-tests.bundle/v1alpha1' ||
    !Array.isArray(bundle.guides) ||
    !Array.isArray(bundle.assets)
  ) {
    throw new Error(`Unsupported or invalid ${DOCS_TESTS_BUNDLE_FILE}.`);
  }

  const guideIds = new Set();
  const guideSlugs = bundle.guides.map((guide, index) => {
    if (
      !guide ||
      typeof guide !== 'object' ||
      typeof guide.id !== 'string' ||
      !guide.id.trim() ||
      typeof guide.slug !== 'string' ||
      typeof guide.title !== 'string' ||
      !guide.title.trim()
    ) {
      throw new Error(
        `Invalid guide at index ${index} in ${DOCS_TESTS_BUNDLE_FILE}.`,
      );
    }
    const slug = normalizeRelativePosixPath(
      guide.slug,
      `Bundle guide ${index} slug`,
    );
    if (slug.includes('/') || !GENERATED_GUIDE_SLUGS.includes(slug)) {
      throw new Error(`Unsupported guide slug in bundle: ${slug}.`);
    }
    if (guideIds.has(guide.id))
      throw new Error(`Duplicate guide id in bundle: ${guide.id}.`);
    guideIds.add(guide.id);
    return slug;
  });
  assertExactSet(guideSlugs, GENERATED_GUIDE_SLUGS, 'Bundle guide slugs');

  const bundleAssetPaths = [];
  for (const [index, asset] of bundle.assets.entries()) {
    if (
      !asset ||
      typeof asset !== 'object' ||
      typeof asset.outputPath !== 'string' ||
      typeof asset.integrity !== 'string' ||
      typeof asset.mediaType !== 'string'
    ) {
      throw new Error(
        `Invalid asset at index ${index} in ${DOCS_TESTS_BUNDLE_FILE}.`,
      );
    }
    const outputPath = normalizeRelativePosixPath(
      asset.outputPath,
      `Bundle asset ${index} outputPath`,
    );
    const [slug] = outputPath.split('/');
    if (!GENERATED_GUIDE_SLUGS.includes(slug) || !outputPath.includes('/')) {
      throw new Error(
        `Bundle asset is outside the supported guide catalog: ${outputPath}.`,
      );
    }
    const expectedMediaType = ALLOWED_IMAGE_TYPES.get(
      path.posix.extname(outputPath).toLowerCase(),
    );
    if (
      !expectedMediaType ||
      asset.mediaType.toLowerCase() !== expectedMediaType
    ) {
      throw new Error(
        `Bundle asset has an unsupported media type: ${outputPath}.`,
      );
    }
    const match = /^sha256-([a-f0-9]{64})$/i.exec(asset.integrity);
    if (!match)
      throw new Error(`Bundle asset has invalid integrity: ${outputPath}.`);
    const assetPath = path.join(assetsRoot, ...outputPath.split('/'));
    assertInside(assetsRoot, assetPath, 'Bundle asset');
    if (!pathExists(assetPath) || !fs.lstatSync(assetPath).isFile()) {
      throw new Error(`Bundle asset is missing: ${outputPath}.`);
    }
    const actualHash = crypto
      .createHash('sha256')
      .update(fs.readFileSync(assetPath))
      .digest('hex');
    if (actualHash !== match[1].toLowerCase()) {
      throw new Error(`Bundle asset integrity mismatch: ${outputPath}.`);
    }
    bundleAssetPaths.push(outputPath);
  }
  assertExactSet(bundleAssetPaths, assetFiles, 'Bundle assets');
}

function assertDisjointSourceAndTargets(sourceRoot, targetRoots) {
  const source = path.resolve(sourceRoot);
  for (const targetRoot of targetRoots) {
    const target = path.resolve(targetRoot);
    const sourceToTarget = path.relative(source, target);
    const targetToSource = path.relative(target, source);
    const contains = (relative) =>
      relative === '' ||
      (!relative.startsWith(`..${path.sep}`) &&
        relative !== '..' &&
        !path.isAbsolute(relative));
    if (contains(sourceToTarget) || contains(targetToSource)) {
      throw new Error(
        'Generated source and Pages output directories must be disjoint.',
      );
    }
  }
}

function validateDestinationRoot(root, label) {
  assertNoSymlinkPathSegments(root, label);
  if (!pathExists(root)) fs.mkdirSync(root, { recursive: true });
  return assertAbsoluteDirectory(root, label);
}

function validateExistingTarget(targetPath, targetRoot) {
  assertInside(targetRoot, targetPath, 'Generated target');
  assertNoSymlinkPathSegments(targetPath, 'Generated target');
  if (!pathExists(targetPath)) return;
  const stat = fs.lstatSync(targetPath);
  if (!stat.isDirectory() || stat.isSymbolicLink()) {
    throw new Error(`Generated target is not a real directory: ${targetPath}`);
  }
  listTree(targetPath, 'Existing generated target');
}

function validateLegacyAssetTarget(targetPath, targetRoot) {
  assertInside(targetRoot, targetPath, 'Legacy generated asset');
  assertNoSymlinkPathSegments(targetPath, 'Legacy generated asset');
  if (!pathExists(targetPath)) return;
  const stat = fs.lstatSync(targetPath);
  if (!stat.isFile() || stat.isSymbolicLink()) {
    throw new Error(
      `Legacy generated asset is not a regular file: ${targetPath}`,
    );
  }
}

function copyFileExclusive(sourcePath, targetPath) {
  fs.mkdirSync(path.dirname(targetPath), { recursive: true });
  fs.copyFileSync(sourcePath, targetPath, fs.constants.COPYFILE_EXCL);
}

function rollbackOperations(completedOperations) {
  const rollbackErrors = [];
  for (const operation of [...completedOperations].reverse()) {
    try {
      if (operation.installed && pathExists(operation.target)) {
        removeRealTree(operation.target, operation.root);
      }
      if (operation.backedUp && pathExists(operation.backup)) {
        fs.renameSync(operation.backup, operation.target);
      }
    } catch (error) {
      rollbackErrors.push(error);
    }
  }
  if (rollbackErrors.length) {
    throw new AggregateError(
      rollbackErrors,
      'Documentation sync rollback failed.',
    );
  }
}

export function syncGeneratedDocs({
  sourceRoot,
  repositoryRoot = REPOSITORY_ROOT,
}) {
  const source = assertAbsoluteDirectory(sourceRoot, 'Generated docs source');
  const repository = assertAbsoluteDirectory(
    repositoryRoot,
    'Pages repository',
  );
  const contentRoot = assertAbsoluteDirectory(
    path.join(source, 'content'),
    'Generated content directory',
  );
  const assetsRoot = assertAbsoluteDirectory(
    path.join(source, 'assets'),
    'Generated assets directory',
  );
  const docsRoot = validateDestinationRoot(
    path.join(repository, 'apps/documentation-page/app/docs'),
    'Documentation routes directory',
  );
  const publicDocsRoot = validateDestinationRoot(
    path.join(repository, 'apps/documentation-page/public/docs'),
    'Documentation assets directory',
  );
  assertDisjointSourceAndTargets(source, [docsRoot, publicDocsRoot]);

  const { expectedPageFiles } = validateContentTree(contentRoot);
  const { assetFiles } = validateAssetsTree(assetsRoot);
  validateOutputManifest(
    contentRoot,
    assetsRoot,
    expectedPageFiles,
    assetFiles,
  );
  validateBundle(contentRoot, assetsRoot, assetFiles);

  for (const slug of GENERATED_GUIDE_SLUGS) {
    validateExistingTarget(path.join(docsRoot, slug), docsRoot);
    validateExistingTarget(path.join(publicDocsRoot, slug), publicDocsRoot);
  }
  for (const fileName of LEGACY_GENERATED_ASSET_FILES) {
    validateLegacyAssetTarget(
      path.join(publicDocsRoot, fileName),
      publicDocsRoot,
    );
  }

  const token = `${process.pid}-${crypto.randomBytes(8).toString('hex')}`;
  const docsStageRoot = path.join(docsRoot, `.docs-sync-stage-${token}`);
  const assetsStageRoot = path.join(
    publicDocsRoot,
    `.docs-sync-stage-${token}`,
  );
  const docsBackupRoot = path.join(docsRoot, `.docs-sync-backup-${token}`);
  const assetsBackupRoot = path.join(
    publicDocsRoot,
    `.docs-sync-backup-${token}`,
  );
  const temporaryRoots = [
    docsStageRoot,
    assetsStageRoot,
    docsBackupRoot,
    assetsBackupRoot,
  ];
  for (const temporaryRoot of temporaryRoots) {
    assertInside(
      temporaryRoot.startsWith(publicDocsRoot) ? publicDocsRoot : docsRoot,
      temporaryRoot,
      'Temporary sync directory',
    );
    if (pathExists(temporaryRoot))
      throw new Error(`Temporary path collision: ${temporaryRoot}`);
    fs.mkdirSync(temporaryRoot, { recursive: true });
  }

  let copiedAssetCount = 0;
  let removedLegacyAssetCount = 0;
  try {
    for (const slug of GENERATED_GUIDE_SLUGS) {
      copyFileExclusive(
        path.join(contentRoot, slug, 'page.md'),
        path.join(docsStageRoot, slug, 'page.md'),
      );
    }
    for (const relativePath of assetFiles) {
      copyFileExclusive(
        path.join(assetsRoot, ...relativePath.split('/')),
        path.join(assetsStageRoot, ...relativePath.split('/')),
      );
      copiedAssetCount += 1;
    }

    const operations = [];
    for (const slug of GENERATED_GUIDE_SLUGS) {
      operations.push({
        backup: path.join(docsBackupRoot, slug),
        root: docsRoot,
        staged: path.join(docsStageRoot, slug),
        target: path.join(docsRoot, slug),
      });
      operations.push({
        backup: path.join(assetsBackupRoot, slug),
        root: publicDocsRoot,
        staged: path.join(assetsStageRoot, slug),
        target: path.join(publicDocsRoot, slug),
      });
    }
    for (const fileName of LEGACY_GENERATED_ASSET_FILES) {
      operations.push({
        backup: path.join(assetsBackupRoot, '__legacy__', fileName),
        root: publicDocsRoot,
        target: path.join(publicDocsRoot, fileName),
      });
    }

    const completedOperations = [];
    try {
      for (const operation of operations) {
        const completed = { ...operation, backedUp: false, installed: false };
        completedOperations.push(completed);
        if (pathExists(operation.target)) {
          fs.mkdirSync(path.dirname(operation.backup), { recursive: true });
          fs.renameSync(operation.target, operation.backup);
          completed.backedUp = true;
        }
        if (operation.staged && pathExists(operation.staged)) {
          fs.renameSync(operation.staged, operation.target);
          completed.installed = true;
        }
        if (!operation.staged && completed.backedUp) {
          removedLegacyAssetCount += 1;
        }
      }
    } catch (error) {
      try {
        rollbackOperations(completedOperations);
      } catch (rollbackError) {
        throw new AggregateError(
          [error, rollbackError],
          'Documentation sync failed and rollback was incomplete.',
        );
      }
      throw error;
    }

    removeRealTree(docsBackupRoot, docsRoot);
    removeRealTree(assetsBackupRoot, publicDocsRoot);
  } finally {
    for (const temporaryRoot of [docsStageRoot, assetsStageRoot]) {
      removeRealTree(
        temporaryRoot,
        temporaryRoot.startsWith(publicDocsRoot) ? publicDocsRoot : docsRoot,
      );
    }
  }

  return {
    copiedAssetCount,
    copiedGuideCount: GENERATED_GUIDE_SLUGS.length,
    removedLegacyAssetCount,
  };
}

if (
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  try {
    const options = parseArguments(process.argv.slice(2));
    if (options.help) {
      printHelp();
    } else {
      const result = syncGeneratedDocs({ sourceRoot: options.sourceRoot });
      console.log(
        `Copied ${result.copiedGuideCount} generated guides and ${result.copiedAssetCount} assets; removed ${result.removedLegacyAssetCount} legacy assets.`,
      );
    }
  } catch (error) {
    console.error(
      `docs:sync failed: ${error instanceof Error ? error.message : String(error)}`,
    );
    process.exitCode = 1;
  }
}

import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';

import {
  GENERATED_GUIDE_SLUGS,
  LEGACY_GENERATED_ASSET_FILES,
} from './config.mjs';
import { syncGeneratedDocs } from './sync-generated-docs.mjs';

function createTemporaryDirectory(name) {
  return fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), `${name}-`));
}

function writeFile(filePath, content) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content);
}

function fileContentHash(filePath) {
  return `sha256:${crypto
    .createHash('sha256')
    .update(fs.readFileSync(filePath))
    .digest('hex')}`;
}

function refreshOutputManifest(source) {
  const manifest = {
    contentHashes: {
      docs: Object.fromEntries(
        source.manifestDocs.map((relativePath) => [
          relativePath,
          fileContentHash(
            path.join(source.contentRoot, ...relativePath.split('/')),
          ),
        ]),
      ),
      images: Object.fromEntries(
        source.manifestImages.map((relativePath) => [
          relativePath,
          fileContentHash(
            path.join(source.assetsRoot, ...relativePath.split('/')),
          ),
        ]),
      ),
    },
    docs: source.manifestDocs,
    images: source.manifestImages,
    schemaVersion: 'docs-tests.output-manifest/v1alpha1',
    targetFingerprints: {
      docs: `sha256:${'1'.repeat(64)}`,
      images: `sha256:${'2'.repeat(64)}`,
    },
  };
  writeFile(source.manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  source.manifest = manifest;
  return manifest;
}

function createRepository(root) {
  fs.mkdirSync(path.join(root, 'apps/documentation-page/app/docs'), {
    recursive: true,
  });
  fs.mkdirSync(path.join(root, 'apps/documentation-page/public/docs'), {
    recursive: true,
  });
}

function createGeneratedSource(root) {
  const contentRoot = path.join(root, 'content');
  const assetsRoot = path.join(root, 'assets');
  fs.mkdirSync(contentRoot, { recursive: true });
  fs.mkdirSync(assetsRoot, { recursive: true });

  const guides = GENERATED_GUIDE_SLUGS.map((slug) => {
    writeFile(
      path.join(contentRoot, slug, 'page.md'),
      `---\ntitle: "${slug}"\n---\n\nGuide for ${slug}.\n`,
    );
    return {
      id: `guide:${slug}`,
      metadata: {},
      sections: [],
      slug,
      title: slug,
    };
  });

  const assetBody = Buffer.from('not-a-real-png-but-stable-for-copy-tests');
  const assetHash = crypto.createHash('sha256').update(assetBody).digest('hex');
  const outputPath = `${GENERATED_GUIDE_SLUGS[0]}/image-${assetHash.slice(0, 16)}.png`;
  writeFile(path.join(assetsRoot, ...outputPath.split('/')), assetBody);
  const bundle = {
    assets: [
      {
        id: `asset:${outputPath}`,
        integrity: `sha256-${assetHash}`,
        mediaType: 'image/png',
        outputPath,
      },
    ],
    guides,
    schemaVersion: 'docs-tests.bundle/v1alpha1',
  };
  writeFile(
    path.join(contentRoot, 'docs-tests.bundle.json'),
    `${JSON.stringify(bundle, null, 2)}\n`,
  );
  const source = {
    assetsRoot,
    bundle,
    contentRoot,
    manifestDocs: [
      ...GENERATED_GUIDE_SLUGS.map((slug) => `${slug}/page.md`),
      'docs-tests.bundle.json',
    ],
    manifestImages: [outputPath],
    manifestPath: path.join(contentRoot, '.docs-tests-manifest.json'),
    outputPath,
  };
  refreshOutputManifest(source);
  return source;
}

function withFixture(run) {
  const root = createTemporaryDirectory('evorto-docs-sync');
  const repositoryRoot = path.join(root, 'pages');
  const sourceRoot = path.join(root, 'generated-docs');
  fs.mkdirSync(repositoryRoot);
  fs.mkdirSync(sourceRoot);
  createRepository(repositoryRoot);
  const source = createGeneratedSource(sourceRoot);
  try {
    return run({ repositoryRoot, root, source, sourceRoot });
  } finally {
    fs.rmSync(root, { force: true, recursive: true });
  }
}

test('copies only the generated catalog and preserves curated paths', () => {
  withFixture(({ repositoryRoot, source, sourceRoot }) => {
    const docsRoot = path.join(
      repositoryRoot,
      'apps/documentation-page/app/docs',
    );
    const publicDocsRoot = path.join(
      repositoryRoot,
      'apps/documentation-page/public/docs',
    );
    const firstSlug = GENERATED_GUIDE_SLUGS[0];
    writeFile(path.join(docsRoot, firstSlug, 'page.md'), 'stale page');
    writeFile(path.join(docsRoot, firstSlug, 'stale.txt'), 'stale file');
    writeFile(path.join(publicDocsRoot, firstSlug, 'stale.png'), 'stale image');
    writeFile(
      path.join(docsRoot, 'send-an-event', 'page.md'),
      'curated transfer page',
    );
    writeFile(
      path.join(publicDocsRoot, 'curated-transfer.png'),
      'curated asset',
    );
    for (const fileName of LEGACY_GENERATED_ASSET_FILES) {
      writeFile(path.join(publicDocsRoot, fileName), 'legacy generated asset');
    }

    const result = syncGeneratedDocs({ repositoryRoot, sourceRoot });

    assert.deepEqual(result, {
      copiedAssetCount: 1,
      copiedGuideCount: GENERATED_GUIDE_SLUGS.length,
      removedLegacyAssetCount: LEGACY_GENERATED_ASSET_FILES.length,
    });
    for (const slug of GENERATED_GUIDE_SLUGS) {
      assert.match(
        fs.readFileSync(path.join(docsRoot, slug, 'page.md'), 'utf8'),
        new RegExp(`Guide for ${slug}`),
      );
    }
    assert.equal(
      fs.existsSync(path.join(docsRoot, firstSlug, 'stale.txt')),
      false,
    );
    assert.equal(
      fs.existsSync(path.join(publicDocsRoot, firstSlug, 'stale.png')),
      false,
    );
    assert.deepEqual(
      fs.readFileSync(
        path.join(publicDocsRoot, ...source.outputPath.split('/')),
      ),
      fs.readFileSync(
        path.join(source.assetsRoot, ...source.outputPath.split('/')),
      ),
    );
    assert.equal(
      fs.readFileSync(path.join(docsRoot, 'send-an-event', 'page.md'), 'utf8'),
      'curated transfer page',
    );
    assert.equal(
      fs.readFileSync(
        path.join(publicDocsRoot, 'curated-transfer.png'),
        'utf8',
      ),
      'curated asset',
    );
    for (const fileName of LEGACY_GENERATED_ASSET_FILES) {
      assert.equal(fs.existsSync(path.join(publicDocsRoot, fileName)), false);
    }
    assert.equal(
      fs.existsSync(path.join(docsRoot, 'docs-tests.bundle.json')),
      false,
    );
    assert.equal(
      fs.existsSync(path.join(docsRoot, '.docs-tests-manifest.json')),
      false,
    );
    assert.equal(
      fs.existsSync(path.join(publicDocsRoot, '.docs-tests-manifest.json')),
      false,
    );
  });
});

