test('rejects path traversal from the docs-tests bundle', () => {
  withFixture(({ repositoryRoot, source, sourceRoot }) => {
    source.bundle.assets[0].outputPath = '../outside.png';
    writeFile(
      path.join(source.contentRoot, 'docs-tests.bundle.json'),
      JSON.stringify(source.bundle),
    );
    refreshOutputManifest(source);
    assert.throws(
      () => syncGeneratedDocs({ repositoryRoot, sourceRoot }),
