  const outputPath = `${GENERATED_GUIDE_SLUGS[0]}/image-${assetHash.slice(0, 16)}.png`;
  writeFile(path.join(assetsRoot, ...outputPath.split('/')), assetBody);
  const bundle = {
    assets: [
      {
        id: `asset:${outputPath}`,
