export function syncGeneratedDocs({
  sourceRoot,
  repositoryRoot = REPOSITORY_ROOT,
}) {
  const source = assertAbsoluteDirectory(sourceRoot, 'Generated docs source');
  const repository = assertAbsoluteDirectory(
    repositoryRoot,
    'Pages repository',
  );
  const contentRoot = assertAbsoluteDirectory(
    path.join(source, 'content'),
    'Generated content directory',
  );
  const assetsRoot = assertAbsoluteDirectory(
    path.join(source, 'assets'),
    'Generated assets directory',
  );
  const docsRoot = validateDestinationRoot(
    path.join(repository, 'apps/documentation-page/app/docs'),
    'Documentation routes directory',
  );
  const publicDocsRoot = validateDestinationRoot(
    path.join(repository, 'apps/documentation-page/public/docs'),
    'Documentation assets directory',
  );
  assertDisjointSourceAndTargets(source, [docsRoot, publicDocsRoot]);

  const { expectedPageFiles } = validateContentTree(contentRoot);
  const { assetFiles } = validateAssetsTree(assetsRoot);
  validateOutputManifest(
    contentRoot,
    assetsRoot,
    expectedPageFiles,
    assetFiles,
  );
  validateBundle(contentRoot, assetsRoot, assetFiles);

  for (const slug of GENERATED_GUIDE_SLUGS) {
    validateExistingTarget(path.join(docsRoot, slug), docsRoot);
    validateExistingTarget(path.join(publicDocsRoot, slug), publicDocsRoot);
  }
  for (const fileName of LEGACY_GENERATED_ASSET_FILES) {
    validateLegacyAssetTarget(
      path.join(publicDocsRoot, fileName),
      publicDocsRoot,
    );
  }

  const token = `${process.pid}-${crypto.randomBytes(8).toString('hex')}`;
  const docsStageRoot = path.join(docsRoot, `.docs-sync-stage-${token}`);
  const assetsStageRoot = path.join(
    publicDocsRoot,
    `.docs-sync-stage-${token}`,
  );
  const docsBackupRoot = path.join(docsRoot, `.docs-sync-backup-${token}`);
  const assetsBackupRoot = path.join(
    publicDocsRoot,
    `.docs-sync-backup-${token}`,
  );
  const temporaryRoots = [
    docsStageRoot,
    assetsStageRoot,
    docsBackupRoot,
    assetsBackupRoot,
  ];
  for (const temporaryRoot of temporaryRoots) {
    assertInside(
      temporaryRoot.startsWith(publicDocsRoot) ? publicDocsRoot : docsRoot,
      temporaryRoot,
      'Temporary sync directory',
    );
    if (pathExists(temporaryRoot))
      throw new Error(`Temporary path collision: ${temporaryRoot}`);
    fs.mkdirSync(temporaryRoot, { recursive: true });
  }

  let copiedAssetCount = 0;
  let removedLegacyAssetCount = 0;
  try {
    for (const slug of GENERATED_GUIDE_SLUGS) {
      copyFileExclusive(
        path.join(contentRoot, slug, 'page.md'),
        path.join(docsStageRoot, slug, 'page.md'),
      );
    }
    for (const relativePath of assetFiles) {
      copyFileExclusive(
        path.join(assetsRoot, ...relativePath.split('/')),
        path.join(assetsStageRoot, ...relativePath.split('/')),
      );
      copiedAssetCount += 1;
    }

    const operations = [];
    for (const slug of GENERATED_GUIDE_SLUGS) {
      operations.push({
        backup: path.join(docsBackupRoot, slug),
        root: docsRoot,
        staged: path.join(docsStageRoot, slug),
        target: path.join(docsRoot, slug),
      });
      operations.push({
        backup: path.join(assetsBackupRoot, slug),
        root: publicDocsRoot,
        staged: path.join(assetsStageRoot, slug),
        target: path.join(publicDocsRoot, slug),
      });
    }
    for (const fileName of LEGACY_GENERATED_ASSET_FILES) {
      operations.push({
        backup: path.join(assetsBackupRoot, '__legacy__', fileName),
        root: publicDocsRoot,
        target: path.join(publicDocsRoot, fileName),
      });
    }

    const completedOperations = [];
    try {
      for (const operation of operations) {
        const completed = { ...operation, backedUp: false, installed: false };
        completedOperations.push(completed);
        if (pathExists(operation.target)) {
          fs.mkdirSync(path.dirname(operation.backup), { recursive: true });
          fs.renameSync(operation.target, operation.backup);
          completed.backedUp = true;
        }
        if (operation.staged && pathExists(operation.staged)) {
          fs.renameSync(operation.staged, operation.target);
          completed.installed = true;
        }
        if (!operation.staged && completed.backedUp) {
          removedLegacyAssetCount += 1;
        }
      }
    } catch (error) {
      try {
        rollbackOperations(completedOperations);
      } catch (rollbackError) {
        throw new AggregateError(
          [error, rollbackError],
          'Documentation sync failed and rollback was incomplete.',
        );
      }
      throw error;
    }

    removeRealTree(docsBackupRoot, docsRoot);
    removeRealTree(assetsBackupRoot, publicDocsRoot);
  } finally {
    for (const temporaryRoot of [docsStageRoot, assetsStageRoot]) {
      removeRealTree(
        temporaryRoot,
        temporaryRoot.startsWith(publicDocsRoot) ? publicDocsRoot : docsRoot,
      );
    }
  }

  return {
    copiedAssetCount,
    copiedGuideCount: GENERATED_GUIDE_SLUGS.length,
    removedLegacyAssetCount,
  };
}

if (
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  try {
    const options = parseArguments(process.argv.slice(2));
    if (options.help) {
      printHelp();
    } else {
      const result = syncGeneratedDocs({ sourceRoot: options.sourceRoot });
      console.log(
        `Copied ${result.copiedGuideCount} generated guides and ${result.copiedAssetCount} assets; removed ${result.removedLegacyAssetCount} legacy assets.`,
      );
    }
  } catch (error) {
    console.error(
      `docs:sync failed: ${error instanceof Error ? error.message : String(error)}`,
    );
    process.exitCode = 1;
  }
}
